edits.newText:
final playingParent = playingPath != null ? p.dirname(playingPath) : '';
final playingInCurrentFolder = playingPath != null &&
    playingPath.isNotEmpty &&
    playingParent == (path ?? '');

// Only treat the affordance as “out of view” when the current
// folder actually contains the playing track (tests often
// inject an empty [LibraryController.tracks] list).
final playingInTracks = playingInCurrentFolder &&
    playingPath != null &&
    libCtrl.tracks.any((t) => t.path == playingPath);

final isVisible = playingInTracks &&
    (!visibilityProbeReady.value ||
        browserController.isTrackVisible(playingPath));

final needsJump = playingPath != null &&
    playingPath.isNotEmpty &&
    (!playingInCurrentFolder ||
        (playingInTracks && !isVisible));

final showJumpGlyph = resolveJumpGlyphVisible(needsJump);

